RARE_UP = {"MYTHIC", "PRIMORDIAL"}

def prompt(bid, domain, rarity):
    p = STYLE.format(accent=ACCENT[domain])
    if rarity in RARE_UP:
        p += EPIC
    return p + "Subject: " + S[bid]

